import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { HomeFeature } from "../types/home";

const NAVY = "#17224d";
const BLUE = "#759ae1";
const BODY = "#5a6473";
const DASH = "1.5px dashed rgba(106, 106, 106, 0.42)";

type FeaturesProps = {
  items?: HomeFeature[];
};

function featureFrame(index: number) {
  const textLeft = index % 2 === 0;
  if (textLeft) {
    if (index === 0) {
      return {
        borderRight: DASH,
        borderBottom: DASH,
        borderBottomRightRadius: "40px",
        pr: { xs: 2.5, md: 6 },
        pb: { xs: 2.5, md: 3 },
      };
    }
    return {
      borderTop: DASH,
      borderRight: DASH,
      borderTopRightRadius: "40px",
      pt: { xs: 2.5, md: 3 },
      pr: { xs: 2.5, md: 6 },
    };
  }

  if (index % 6 === 5) {
    return {
      borderBottom: DASH,
      borderLeft: DASH,
      borderBottomLeftRadius: "40px",
      pb: { xs: 2.5, md: 3 },
      pl: { xs: 2.5, md: 6 },
    };
  }

  return {
    borderTop: DASH,
    borderLeft: DASH,
    borderTopLeftRadius: "40px",
    pt: { xs: 2.5, md: 3 },
    pl: { xs: 2.5, md: 6 },
  };
}

export default function Features({ items = [] }: FeaturesProps) {
  if (!items.length) return null;

  return (
    <Box sx={{ py: { xs: 5, md: 10 }, backgroundColor: "#fff" }}>
      <Container maxWidth="xl" sx={{ px: { xs: 2, md: 5 } }}>
        <Stack spacing={{ xs: 6, md: 10 }}>
          {items.map((item, index) => {
            const image = mediaUrl(item.image);
            const textLeft = index % 2 === 0;
            return (
              <Stack
                key={item.id || item.title}
                direction={{ xs: "column", md: textLeft ? "row" : "row-reverse" }}
                alignItems="center"
                spacing={{ xs: 3, md: 6 }}
              >
                <Box sx={{ flex: 1, width: "100%", ...featureFrame(index) }}>
                  <Typography
                    sx={{
                      color: BLUE,
                      fontSize: { xs: 32, md: 54 },
                      fontWeight: 900,
                      letterSpacing: "1.08px",
                      lineHeight: 1.2,
                      mb: 0,
                    }}
                  >
                    {String(index + 1).padStart(2, "0")}
                  </Typography>
                  <Typography
                    component="h2"
                    sx={{
                      color: NAVY,
                      fontSize: { xs: 22, md: 36 },
                      fontWeight: 600,
                      lineHeight: 1.15,
                      letterSpacing: "0.5px",
                      mb: 1.5,
                    }}
                  >
                    {item.title}
                  </Typography>
                  <BlocksText
                    content={item.description}
                    sx={{
                      color: BODY,
                      fontSize: { xs: 14, md: 18 },
                      lineHeight: 1.65,
                      letterSpacing: "0.32px",
                      "& p": { mb: 0 },
                      "& strong": { fontWeight: 700, color: BODY },
                    }}
                  />
                </Box>
                {image ? (
                  <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
                    <Box
                      component="img"
                      src={image}
                      alt={item.image?.alternativeText || item.title}
                      sx={{
                        width: "100%",
                        maxWidth: { xs: 360, md: 500 },
                        display: "block",
                        mx: textLeft ? { xs: "auto", md: 0 } : "auto",
                        ml: textLeft ? { md: "auto" } : { xs: "auto", md: 0 },
                      }}
                    />
                  </Box>
                ) : null}
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
